def unique_emails(values: list[str]) -> list[str]:
       seen: set[str] = set()
       result: list[str] = []
       for value in values:
           normalized = value.strip().lower()
           if normalized and normalized not in seen:
               seen.add(normalized)
               result.append(normalized)
       return result

Interview bridge: "I choose data structures based on access patterns, not habit. For
 import pipelines I consider memory, normalization, duplicate policy and error reporting,
 as well as algorithmic complexity."

