function parseCount(value: unknown): Result<number> {
     if (typeof value !== "number" || !Number.isInteger(value)) {
       return { ok: false, error: "Expected an integer" };
     }
     if (value < 0) return { ok: false, error: "Must be nonnegative" };
     return { ok: true, value };
   }

const result = parseCount(12);
   if (result.ok) console.log(result.value); // 12
   else console.log(result.error);

